export class Canvas3DWireframe {
  public div: HTMLElement;
  public renderer: RendererCanvas3DWireframe;
  public pts = [];
  public lns = [];
  public t = 0.0;
  constructor(id: string) {
    this.div = document.getElementById(id);
    this.renderer = new RendererCanvas3DWireframe(id);
    this.renderer.pts = this.pts;

    this.init();
    this.update();
    this.render();
  }
  public init() {
    // TODO
  }
  public update() {
    // TODO
  }
  public render() {
    requestAnimationFrame(() => {
      this.render();
    });
    this.update();
    this.renderer.render();
  }
  public destroy() {
    // this.renderer.destroy();
    try {
      while (this.div && this.div.lastElementChild) {
        const lastChild = this.div.lastElementChild as Node;
        this.div.removeChild(lastChild);
      }
    } catch (error) {
      console.error("Error removing child elements:", error);
    }
  }
}

export class RendererCanvas3DWireframe {
  public render: () => void;
  public ctx: CanvasRenderingContext2D
  public vecs = [];
  public pts = [];
  public cps = [];
  public circle = [];
  public polylines = [];

  public showFrame = false;
  public showPoint = true;
  
  constructor(id) {
    const div = document.getElementById(id);
    const bounding = div.getBoundingClientRect();
    const canvas = document.createElement("canvas");
    canvas.width = bounding.width;
    canvas.height = bounding.height;
    div.appendChild(canvas);

    const ctx = canvas.getContext("2d");
    this.ctx = ctx
    let angleX = -Math.PI / 2;
    let angleY = 0;
    let dragging = false;
    let panning = false;
    let zoom = 1;
    let lastMouseX = 0;
    let lastMouseY = 0;
    let offsetX = 0;
    let offsetY = 0;
    let panStartX = 0;
    let panStartY = 0;
    let fov = 500;


    const rotate = (point, angleX, angleY) => {
      const cosX = Math.cos(angleX);
      const sinX = Math.sin(angleX);
      const cosY = Math.cos(angleY);
      const sinY = Math.sin(angleY);

      // (swap Y and Z for Z-up)
      let x = point.x * cosY - point.y * sinY;
      let y = point.x * sinY + point.y * cosY;

      let z = point.z * cosX - y * sinX;
      y = point.z * sinX + y * cosX;

      return { x, y, z };
    };

    const project = (point) => {
      const scale = (fov / (fov + point.y)) * zoom; // Z-axis is now vertical
      return {
        x: point.x * scale + canvas.width / 2 + offsetX,
        y: -point.z * scale + canvas.height / 2 + offsetY, // Invert Z for canvas Y-axis
      };
    };

    const projectionToView = (p) => {
      let rotated = rotate(p, angleX, angleY);
      return project(rotated);
    }

    const rendering = () => {
      // requestAnimationFrame(() => {
      //   rendering();
      // });
      // console.log('rendering...', this.pts)

      ctx.clearRect(0, 0, canvas.width, canvas.height);


      for(let i = 0; i < this.polylines.length; ++i) {
        let col = "red";
        if (i % 3 === 1) {
          col = "green";
        } else if (i % 3 === 2) {
          col = "blue";
        }
        ctx.strokeStyle = col;
        ctx.beginPath();
        for(let j = 0; j < this.polylines[i].length; ++j) {
          let projectPt = projectionToView(this.polylines[i][j])
          if (j === 0 ) {
            ctx.moveTo(projectPt.x, projectPt.y)
          } else {
            ctx.lineTo(projectPt.x, projectPt.y)
          }
        }
        ctx.stroke();
      }


      const vsForLine = [];

      if (this.showPoint) {
        this.pts.forEach((point) => {
          const rotated = rotate(point, angleX, angleY);
          const projected = project(rotated);
  
          const depthScale = (fov / (fov + rotated.y)) * zoom;
          let radius = point.size * depthScale;
          radius = radius < 0.1 ? 0.1 : radius;
  
          ctx.beginPath();
          ctx.arc(projected.x, projected.y, radius, 0, Math.PI * 2);
          ctx.fillStyle = point.color ? point.color : "#f00";
          ctx.fill();
        });
      }

      let count = 0;

      // console.log(this.vecs.length)

      if (this.showFrame) {
        this.vecs.forEach((vs) => {
          // console.log(vs)

          const rotated = rotate(vs[0], angleX, angleY);
          const projected = project(rotated);

          vsForLine.push(projected);

          const rotated2 = rotate(vs[1], angleX, angleY);
          const projected2 = project(rotated2);

          let col = "red";
          if (count % 3 === 1) {
            col = "green";
          } else if (count % 3 === 2) {
            col = "blue";
          }

          drawVector(ctx, projected, projected2, col);
          // console.log(count)
          count++;
        });
      }
      // drawCurve(ctx, vsForLine);





      this.cps.forEach((point) => {
        const rotated = rotate(point, angleX, angleY);
        const projected = project(rotated);

        const depthScale = (fov / (fov + rotated.y)) * zoom;
        let radius = 3 * depthScale;
        radius = radius < 0.1 ? 0.1 : radius;

        ctx.beginPath();
        ctx.arc(projected.x, projected.y, radius, 0, Math.PI * 2);
        ctx.fillStyle = "#000";
        ctx.fill();
      });

      ctx.beginPath();
      for (let i = 0; i < this.cps.length; ++i) {
        const rotated = rotate(this.cps[i], angleX, angleY);
        const projected = project(rotated);

        if (i === 0) {
          ctx.moveTo(projected.x, projected.y);
        } else {
          ctx.lineTo(projected.x, projected.y);
        }
      }
      ctx.lineWidth = 1;
      ctx.strokeStyle = "rgba(0,0,0, 0.75)";
      ctx.stroke();

      if (this.circle[0]) {

        drawCircle(ctx, this.circle[0], this.circle[1], projectionToView)
       
      }
    };
    this.render = () => rendering();

    canvas.addEventListener("mousedown", (e) => {
      if (e.button === 2) {
        dragging = true;
      } else if (e.button === 0) {
        if (e.altKey) {
          dragging = true;
        } else {
          panning = true;
          panStartX = e.clientX - offsetX;
          panStartY = e.clientY - offsetY;
        }
      }
      lastMouseX = e.clientX;
      lastMouseY = e.clientY;
    });

    canvas.addEventListener("mousemove", (e) => {
      if (dragging) {
        const dx = e.clientX - lastMouseX;
        const dy = e.clientY - lastMouseY;
        angleX -= dy * 0.01;
        angleY += dx * 0.01;
        lastMouseX = e.clientX;
        lastMouseY = e.clientY;
        //   rendering();
      } else if (panning) {
        offsetX = e.clientX - panStartX;
        offsetY = e.clientY - panStartY;
        //   rendering();
      }
    });

    canvas.addEventListener("mouseup", () => {
      dragging = false;
      panning = false;
    });

    canvas.addEventListener("contextmenu", (e) => {
      e.preventDefault();
    });

    canvas.addEventListener("wheel", (e) => {
      const mouseX = e.clientX - canvas.getBoundingClientRect().left;
      const mouseY = e.clientY - canvas.getBoundingClientRect().top;

      const prevZoom = zoom;
      const zoomSpeed = Math.max(0.001, zoom * 0.02); // zoom speed based on zoom level

      zoom += e.deltaY * -zoomSpeed;
      zoom = Math.min(Math.max(zoom, 0.1), 50);

      const scaleChange = zoom / prevZoom;

      offsetX -= (mouseX - canvas.width / 2 - offsetX) * (scaleChange - 1);
      offsetY -= (mouseY - canvas.height / 2 - offsetY) * (scaleChange - 1);

      // rendering();
    });

    rendering();
  }
}

const drawVector = (ctx, origin, vector, color = "black") => {
  const start = origin;
  const end = vector;
  // console.log(color)
  ctx.beginPath();  
  ctx.moveTo(start.x, start.y);
  ctx.lineTo(end.x, end.y);
  ctx.closePath();
  
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.stroke();
};

const drawCurve = (ctx, vs) => {
  ctx.beginPath();
  ctx.strokeStyle = "blue";
  ctx.lineWidth = 2;

  // const steps = 100;
  for (let i = 0; i < vs.length; i++) {
    if (i === 0) {
      ctx.moveTo(vs[i].x, vs[i].y);
    } else {
      ctx.lineTo(vs[i].x, vs[i].y);
    }
  }
  ctx.stroke();
};

const drawCircle = (ctx, cp, radius, projectionToView ) => {

  ctx.beginPath();
  for (let angle = 0; angle <= 360; angle++) {

    const radians = (angle * Math.PI) / 180;

    const x = cp.x + radius * Math.cos(radians);
    const y = cp.y + radius * Math.sin(radians);
    const z = cp.z

    let projected = projectionToView({x,y,z})
    if (angle === 0) {
      ctx.moveTo(projected.x, projected.y);
    } else {
      ctx.lineTo(projected.x, projected.y);
    }
  }
  ctx.closePath();
  ctx.stroke();
};
